package com.aadil.ecommerce.services;import com.aadil.ecommerce.dtos.ProductRequestDTO;import com.aadil.ecommerce.dtos.ProductResponseDTO;import com.aadil.ecommerce.entities.ProductEntity;import com.aadil.ecommerce.enums.ProductSortBy;import com.aadil.ecommerce.enums.SortDirections;import com.aadil.ecommerce.exceptions.InvalidRequestException;import com.aadil.ecommerce.exceptions.ProductNotFoundException;import com.aadil.ecommerce.repositories.ProductRepository;import com.aadil.ecommerce.responses.PaginatedResponse;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;@Service@RequiredArgsConstructorpublic class ProductService {    private final ProductRepository productRepository;   private ProductResponseDTO mapToProductDTO (ProductEntity productEntity){       return new ProductResponseDTO               (productEntity.getId()               ,productEntity.getProductName(),               productEntity.getDescription(),               productEntity.getPrice(),               productEntity.getStockQuantity(),               productEntity.getCategory(),               productEntity.getCreatedAt(),               productEntity.getUpdatedAt());   }   private ProductEntity mapToProductTable (ProductRequestDTO dto){       ProductEntity productEntity = new ProductEntity();       productEntity.setProductName(dto.getProductName());       productEntity.setDescription(dto.getDescription());       productEntity.setPrice(dto.getPrice());       productEntity.setStockQuantity(dto.getStockQuantity());       productEntity.setCategory(dto.getCategory());        return productEntity;   }   @Transactional   public ProductResponseDTO createProduct (ProductRequestDTO dto){       ProductEntity product = mapToProductTable(dto);       ProductEntity savedProduct = productRepository.save(product);       return mapToProductDTO(savedProduct);   }   public ProductResponseDTO getProductById (Long id){      ProductEntity product = productRepository.findById(id).orElseThrow(()->new ProductNotFoundException("Product is NOT found by ID: "+id));      return mapToProductDTO(product);   }    public PaginatedResponse<List<ProductResponseDTO>> getAllProducts (String search, int page, int size, ProductSortBy productSortBy, SortDirections sortDirection){       if (search != null && !search.isBlank()){           search = search.trim().toLowerCase();       }      if (page < 0){          throw new InvalidRequestException("Page should NOT be below 0");      }      if (size <= 0){          throw new InvalidRequestException("Size should be greater than 0");      }       else if (size > 100){           throw new InvalidRequestException("Size should NOT be exceed 100");       }       if (productSortBy == null){           productSortBy = ProductSortBy.CREATED_AT;       }       if (sortDirection == null){           sortDirection = SortDirections.DESC;       }        Sort.Direction sortDirect = sortDirection == SortDirections.ASC?                Sort.Direction.ASC: Sort.Direction.DESC;       Sort sort = Sort.by(new Sort.Order(sortDirect,productSortBy.getProductSortBy()));        Pageable pageable = PageRequest.of(page,size,sort);        Page<ProductEntity> products;        if (search == null || search.isBlank()){            products = productRepository.findAll(pageable);        }        else {            products = productRepository.findByProductNameContainingIgnoreCaseOrDescriptionContainingIgnoreCase(search.trim(),search.trim(),pageable);        }        List<ProductResponseDTO> contents = products.getContent().stream().map(this::mapToProductDTO).toList();        return new PaginatedResponse<>(contents,products.getNumber(),products.getSize(),products.getTotalElements(),products.getTotalPages(),products.isLast());    }    @Transactional    public ProductResponseDTO updateProduct (Long id,ProductRequestDTO dto){       ProductEntity product = productRepository.findById(id).orElseThrow(()->new ProductNotFoundException("Product is NOT found: "+id));       product.setProductName(dto.getProductName());       product.setDescription(dto.getDescription());       product.setPrice(dto.getPrice());       product.setStockQuantity(dto.getStockQuantity());       product.setCategory(dto.getCategory());       return mapToProductDTO(product);    }    @Transactional    public void deleteProductById (Long id,boolean confirm){        productRepository.findById(id).orElseThrow(()->new ProductNotFoundException("Product is NOT found: "+id));       if (!confirm){           throw new InvalidRequestException("Type ?confirm=true to proceed");       }       productRepository.deleteById(id);    }    @Transactional    public List<ProductResponseDTO> createBulkProducts (List<ProductRequestDTO> dtos){       if (dtos == null){           throw new InvalidRequestException("Product list cannot be NULL");       }       if (dtos.isEmpty()){           throw new InvalidRequestException("Lists cannot be EMPTY");       }       for (ProductRequestDTO dto : dtos){           if (dto == null){               throw new InvalidRequestException("Product set is NULL");           }       }        if (dtos.size() > 100) {            throw new InvalidRequestException("Size has exceeded, Maximum 100 products are allowed");        }        List<ProductEntity> products = dtos.stream().map(this::mapToProductTable).toList();        List<ProductEntity> savedProducts = productRepository.saveAll(products);        return savedProducts.stream().map(this::mapToProductDTO).toList();    }}